def dict(self) -> Dict[str, Optional[str]]:
    """Return dotenv as dict"""
    if self._dict is not None:
        return self._dict

    raw_values = self.parse()

    if self.interpolate:
        self._dict = OrderedDict(
            resolve_variables(raw_values, override=self.override)
        )
    else:
        self._dict = OrderedDict(raw_values)

    return self._dict

def check(spec, values, expected, constructor=None, call=None):
    original = list(values)
    seen = []
    def once():
        for item in original:
            seen.append(item)
            yield item
    result = list(SpecifierSet(spec, prereleases=constructor).filter(once(), prereleases=call))
    assert [str(v) for v in result] == expected, result
    assert seen == original and all(any(v is item for item in original) for v in result)
if case == 'fallback':
    check('>=1,<2', ['0.9', '1.5a1', '2.1'], ['1.5a1'])
    check('<2,>=1', ['1.6rc1', '1.5a1', '1.6rc1'], ['1.6rc1', '1.5a1', '1.6rc1'])
elif case == 'matching-finals':
    check('>=1,<2', ['1.5a1', '1.4', '2.1', '1.6rc1', '1.4'], ['1.4', '1.4'])
    check('>=1,<2', ['1.5a1', '1.4.post1'], ['1.4.post1'])

elif case == 'site-defaults':
    for value in ['', ':relative::', 'relative:also-relative']:
        os.environ['XDG_DATA_DIRS'] = value; os.environ['XDG_CONFIG_DIRS'] = value
        instance = Unix('demo', version='2', multipath=True)
        assert instance.site_data_dir == '/usr/local/share/demo/2:/usr/share/demo/2'
        assert instance.site_config_dir == '/etc/xdg/demo/2'

def _site_config_dirs(self) -> list[str]:
    path = os.environ.get("XDG_CONFIG_DIRS", "")
    paths = [p for p in path.split(os.pathsep) if os.path.isabs(p)]
    if not paths:
        paths = ("/etc/xdg").split(os.pathsep)
    return [self._append_app_name_and_version(p) for p in paths]

def _append_app_name_and_version(self, *base: str) -> str:
    params = list(base[1:])
    if self.appname:
        params.append(self.appname)
        if self.version:
            params.append(self.version)
    path = os.path.join(base[0], *params)  # noqa: PTH118
    self._optionally_create_directory(path)
    return path
